begin;
update nexora.modules set description='Integre cliente, servidor e APIs, proteja secrets, teste, publique e monitore a aplicação, concluindo com um projeto final demonstrável.' where course_id=(select id from nexora.courses where slug='programador-master') and position=9;
update nexora.lessons set objective='Explicar responsabilidades de cliente, servidor e API e desenhar um fluxo de dados sem expor regras ou segredos indevidamente.',estimated_minutes=36,lab_type='api',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O frontend precisa listar pedidos, mas o banco não deve ficar acessível diretamente ao navegador sem política ou camada de serviço."},{"type":"concept","title":"Arquitetura cliente, servidor e API","body":"Em uma arquitetura web típica, o cliente apresenta interface e envia requisições; o servidor aplica regras, autorização e acesso a dados; a API define o contrato entre as partes. Essa separação permite evoluir interfaces sem duplicar regra de negócio e impede que credenciais de banco sejam incorporadas ao frontend. O limite exato varia por tecnologia, mas responsabilidades precisam estar explícitas."},{"type":"mechanics","title":"Como aplicar","items":["Cliente não deve carregar segredos de servidor.","API expõe apenas operações autorizadas.","Servidor valida entrada e autorização.","Contrato deve ser claro para ambos os lados."]},{"type":"example","title":"Exemplo","body":"Browser → GET /api/pedidos → servidor valida usuário → consulta banco → retorna JSON autorizado → browser renderiza."},{"type":"mistake","title":"Erro comum","body":"Acessar banco com credencial administrativa embutida no JavaScript enviado ao usuário."},{"type":"guided","question":"Onde deve ficar uma chave secreta usada pelo backend?","options":["No ambiente seguro do servidor.","No HTML público.","No README."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Explicar responsabilidades de cliente, servidor e API e desenhar um fluxo de dados sem expor regras ou segredos indevidamente.","Cliente não deve carregar segredos de servidor.","API expõe apenas operações autorizadas.","Servidor valida entrada e autorização."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Arquitetura cliente, servidor e API';
update nexora.lessons set objective='Escolher métodos e status HTTP coerentes e interpretar headers e corpo para diagnosticar integrações.',estimated_minutes=42,lab_type='api',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma API responde 200 mesmo quando falha validação, obrigando o cliente a adivinhar se a operação funcionou."},{"type":"concept","title":"HTTP, métodos, status e headers","body":"HTTP transporta requisições e respostas. Métodos comunicam intenção: GET leitura, POST criação/ação, PUT/PATCH atualização e DELETE remoção, conforme contrato. Status 2xx indica sucesso; 4xx sinaliza problema na requisição/cliente; 5xx indica falha de servidor. Headers carregam metadados como tipo de conteúdo e autorização."},{"type":"mechanics","title":"Como aplicar","items":["Use status que represente o resultado real.","Não devolva 200 para todo cenário.","Valide Content-Type e Accept quando relevante.","Registre request ID quando ajuda diagnóstico."]},{"type":"example","title":"Exemplo","body":"POST /api/produtos → 201 Created\\nGET /api/produtos/999 → 404 Not Found\\nPOST inválido → 422 Unprocessable Content"},{"type":"mistake","title":"Erro comum","body":"Usar 500 para qualquer erro, inclusive payload inválido enviado pelo cliente."},{"type":"guided","question":"Qual classe de status representa erro de validação do cliente?","options":["4xx","2xx","3xx sempre"],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Escolher métodos e status HTTP coerentes e interpretar headers e corpo para diagnosticar integrações.","Use status que represente o resultado real.","Não devolva 200 para todo cenário.","Valide Content-Type e Accept quando relevante."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='HTTP, métodos, status e headers';
update nexora.lessons set objective='Desenhar endpoints centrados em recursos, com nomes consistentes, operações previsíveis e payloads coerentes.',estimated_minutes=46,lab_type='api',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A API possui /criarProduto, /listaProdutos, /deletarProduto e /produtoAtualizar, cada rota com convenção diferente."},{"type":"concept","title":"REST e desenho de endpoints","body":"REST não é apenas usar JSON. Um desenho orientado a recursos usa URLs que representam entidades e métodos HTTP que representam operações. Consistência reduz carga cognitiva: /produtos para coleção, /produtos/{id} para item. Paginação, filtros e erros também devem seguir padrões estáveis. O objetivo é um contrato previsível, não purismo."},{"type":"mechanics","title":"Como aplicar","items":["Nomeie recursos com substantivos consistentes.","Use método para expressar operação.","Padronize erros e envelopes quando usados.","Versione mudanças incompatíveis conscientemente."]},{"type":"example","title":"Exemplo","body":"GET /api/produtos\\nPOST /api/produtos\\nGET /api/produtos/42\\nPATCH /api/produtos/42\\nDELETE /api/produtos/42"},{"type":"mistake","title":"Erro comum","body":"Criar uma rota diferente para cada verbo e perder consistência sem necessidade."},{"type":"guided","question":"Qual endpoint representa melhor a coleção de produtos?","options":["/api/produtos","/api/criarProdutoAgora","/api/getTodos"],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Desenhar endpoints centrados em recursos, com nomes consistentes, operações previsíveis e payloads coerentes.","Nomeie recursos com substantivos consistentes.","Use método para expressar operação.","Padronize erros e envelopes quando usados."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='REST e desenho de endpoints';
update nexora.lessons set objective='Distinguir autenticação de autorização e proteger operações de API por identidade, papel e propriedade do recurso.',estimated_minutes=50,lab_type='auth',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um usuário autenticado altera o ID na URL e consegue ler o pedido de outro usuário."},{"type":"concept","title":"Autenticação e autorização em APIs","body":"Autenticação responde quem está fazendo a requisição; autorização responde se essa identidade pode executar a ação sobre aquele recurso. Verificar login não basta. Cada operação sensível precisa aplicar regra de acesso no servidor ou camada de dados. Tokens e sessões devem ser validados, expirados e tratados como credenciais."},{"type":"mechanics","title":"Como aplicar","items":["Autentique antes de confiar em identidade.","Autorize por ação e recurso.","Nunca confie apenas em controle do frontend.","Evite expor tokens em logs ou URLs."]},{"type":"example","title":"Exemplo","body":"GET /api/pedidos/42 → validar token → carregar pedido → confirmar pedido.user_id == usuário atual ou papel autorizado → retornar."},{"type":"mistake","title":"Erro comum","body":"Esconder botão ''Excluir'' para usuários comuns e deixar o endpoint sem verificação de permissão."},{"type":"guided","question":"O que vem depois de identificar quem é o usuário?","options":["Verificar se pode executar a ação.","Assumir acesso total.","Enviar senha de volta."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Distinguir autenticação de autorização e proteger operações de API por identidade, papel e propriedade do recurso.","Autentique antes de confiar em identidade.","Autorize por ação e recurso.","Nunca confie apenas em controle do frontend."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Autenticação e autorização em APIs';
update nexora.lessons set objective='Consumir uma API no frontend modelando loading, sucesso, vazio, erro e cancelamento quando necessário.',estimated_minutes=48,lab_type='api',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A tela fica em branco se a API falha e o usuário não sabe se está carregando ou se não existem dados."},{"type":"concept","title":"Consumindo APIs no frontend","body":"Integração de frontend é uma máquina de estados. Antes da resposta há loading; sucesso pode conter dados ou coleção vazia; falha precisa de mensagem e opção de recuperação quando apropriado. O payload recebido deve ser validado antes de renderizar. Requisições obsoletas podem precisar ser canceladas em buscas ou navegação rápida."},{"type":"mechanics","title":"Como aplicar","items":["Modele loading/erro/vazio/sucesso.","Verifique response.ok.","Valide campos esperados.","Evite atualizar interface com resposta obsoleta."]},{"type":"example","title":"Exemplo","body":"estado=''loading'' → fetch → status → JSON válido → estado=''success''; catch → estado=''error''."},{"type":"mistake","title":"Erro comum","body":"Renderizar diretamente data.items.map sem confirmar se items existe e é array."},{"type":"guided","question":"Qual estado deve existir além de sucesso e erro?","options":["Loading, e muitas vezes vazio.","Somente hover.","Print."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Consumir uma API no frontend modelando loading, sucesso, vazio, erro e cancelamento quando necessário.","Modele loading/erro/vazio/sucesso.","Verifique response.ok.","Valide campos esperados."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Consumindo APIs no frontend';
update nexora.lessons set objective='Conectar formulário e dados do frontend a endpoints reais, alinhando validação, contrato e mensagens de erro entre as camadas.',estimated_minutes=52,lab_type='api',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O frontend chama campo telefone, o backend espera whatsapp e o erro aparece apenas em produção."},{"type":"concept","title":"Integrando frontend e backend","body":"Integração exige contrato compartilhado. Nomes de campos, tipos, obrigatoriedade, status e formato de erro precisam estar alinhados. Testar frontend e backend isoladamente reduz área de diagnóstico; depois, o teste integrado verifica serialização, CORS, autenticação e mensagens. A API continua sendo a fonte final de validação."},{"type":"mechanics","title":"Como aplicar","items":["Documente payload e resposta.","Teste endpoint isolado antes da tela.","Mapeie erros de API para feedback de usuário.","Evite duplicar regras divergentes entre camadas."]},{"type":"example","title":"Exemplo","body":"POST /api/leads body {nome,contato} → 201 {id,...}; 422 {errors:{contato:''inválido''}} → frontend associa mensagem ao campo."},{"type":"mistake","title":"Erro comum","body":"Tratar qualquer falha como ''Erro inesperado'' e perder a informação útil retornada pela API."},{"type":"guided","question":"Qual prática reduz conflitos de integração?","options":["Contrato explícito e testado.","Nomes de campo diferentes em cada camada.","Depurar tudo ao mesmo tempo."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Conectar formulário e dados do frontend a endpoints reais, alinhando validação, contrato e mensagens de erro entre as camadas.","Documente payload e resposta.","Teste endpoint isolado antes da tela.","Mapeie erros de API para feedback de usuário."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Integrando frontend e backend';
update nexora.lessons set objective='Separar configuração pública de segredos e carregar credenciais por ambiente sem versioná-las no repositório.',estimated_minutes=44,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"O que fazer se um segredo foi commitado publicamente?","options":["Rotacionar/revogar e remover do fluxo.","Apenas apagar a linha atual.","Renomear a variável."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma API key foi commitada no GitHub e depois removida do arquivo. O segredo continua no histórico e deve ser rotacionado."},{"type":"concept","title":"Variáveis de ambiente e secrets","body":"Variáveis de ambiente permitem configurar URLs, chaves e comportamento sem alterar código. Nem toda variável é secreta: URL pública pode ser exposta; chave administrativa não. Segredos precisam ficar no ambiente seguro de execução e nunca no bundle frontend. Se um segredo vaza, apagar do código não basta: ele deve ser revogado ou rotacionado."},{"type":"mechanics","title":"Como aplicar","items":["Classifique configuração pública x secreta.","Use arquivos .env locais fora do Git.","Configure secrets na plataforma de deploy.","Rotacione credenciais comprometidas."]},{"type":"example","title":"Exemplo","body":"Frontend: API_BASE_URL pode ser pública. Backend: DATABASE_URL e API_SECRET ficam em secret/environment seguro."},{"type":"mistake","title":"Erro comum","body":"Prefixar uma variável como PUBLIC e colocar segredo nela. O nome não torna o valor seguro."},{"type":"guided","question":"O que fazer se um segredo foi commitado publicamente?","options":["Rotacionar/revogar e remover do fluxo.","Apenas apagar a linha atual.","Renomear a variável."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Separar configuração pública de segredos e carregar credenciais por ambiente sem versioná-las no repositório.","Classifique configuração pública x secreta.","Use arquivos .env locais fora do Git.","Configure secrets na plataforma de deploy."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Variáveis de ambiente e secrets';
update nexora.lessons set objective='Executar uma matriz mínima de testes funcionais, responsivos, acessíveis e de erro antes de promover uma versão.',estimated_minutes=50,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual caso costuma revelar falhas ignoradas pelo caminho feliz?","options":["Limites e erros.","Somente cor do logo.","Nome do repositório."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O fluxo feliz funciona, mas formulário vazio, rede lenta e mobile nunca foram testados."},{"type":"concept","title":"Testes essenciais antes de publicar","body":"QA de publicação precisa cobrir comportamento normal, fronteiras e falhas. Teste o fluxo principal, entradas inválidas, autorização, telas vazias, mobile e navegadores relevantes. Automatize o que se repete, mas mantenha smoke test da experiência crítica. Um deploy não deve ser a primeira vez que integração completa é exercitada."},{"type":"mechanics","title":"Como aplicar","items":["Teste caminho feliz e erro.","Inclua mobile e teclado.","Valide autenticação/autorização.","Faça smoke test pós-deploy."]},{"type":"example","title":"Exemplo","body":"Matriz mínima: login válido/inválido; criar/editar/excluir; sem dados; API 500; viewport pequeno; teclado; logout; recarga profunda."},{"type":"mistake","title":"Erro comum","body":"Considerar ''compilou'' como sinônimo de ''está pronto para produção''."},{"type":"guided","question":"Qual caso costuma revelar falhas ignoradas pelo caminho feliz?","options":["Limites e erros.","Somente cor do logo.","Nome do repositório."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Executar uma matriz mínima de testes funcionais, responsivos, acessíveis e de erro antes de promover uma versão.","Teste caminho feliz e erro.","Inclua mobile e teclado.","Valide autenticação/autorização."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Testes essenciais antes de publicar';
update nexora.lessons set objective='Planejar build, configuração, migrações, publicação e rollback de frontend/backend sem depender de passos manuais obscuros.',estimated_minutes=54,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual informação ajuda a diagnosticar qual versão está em produção?","options":["Commit/build ID.","Nome do navegador.","Cor do botão."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O deploy funciona apenas quando o autor lembra uma sequência não documentada de comandos e variáveis."},{"type":"concept","title":"Deploy de frontend e backend","body":"Deploy é um processo reproduzível de transformar código versionado em versão executável. Deve definir build, variáveis, migrações, artefatos e smoke test. Frontend estático e backend podem ter pipelines diferentes. Rollback ou promoção segura exige saber qual commit está em produção. Automatizar reduz variação humana, mas o pipeline precisa falhar claramente quando requisitos não são atendidos."},{"type":"mechanics","title":"Como aplicar","items":["Associe deploy a commit identificável.","Valide secrets antes do build.","Aplique migrações de forma controlada.","Execute health/smoke test após publicar."]},{"type":"example","title":"Exemplo","body":"push main → CI/testes → build → deploy backend → health check → deploy frontend → smoke do fluxo crítico."},{"type":"mistake","title":"Erro comum","body":"Editar arquivo diretamente no servidor para corrigir produção e não registrar a mudança no repositório."},{"type":"guided","question":"Qual informação ajuda a diagnosticar qual versão está em produção?","options":["Commit/build ID.","Nome do navegador.","Cor do botão."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Planejar build, configuração, migrações, publicação e rollback de frontend/backend sem depender de passos manuais obscuros.","Associe deploy a commit identificável.","Valide secrets antes do build.","Aplique migrações de forma controlada."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Deploy de frontend e backend';
update nexora.lessons set objective='Usar logs, métricas, health checks e correlação de requisições para localizar falhas sem expor dados sensíveis.',estimated_minutes=50,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual dado ajuda a correlacionar a mesma operação entre serviços?","options":["Request/correlation ID.","Cor do terminal.","Número aleatório sem registro."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Usuário relata ''deu erro'', mas não há log, timestamp ou request ID. A equipe precisa adivinhar."},{"type":"concept","title":"Observabilidade e diagnóstico de erros","body":"Observabilidade transforma comportamento interno em sinais. Logs estruturados registram eventos; métricas mostram tendências; health checks indicam disponibilidade; tracing/request IDs ajudam a seguir uma operação. O objetivo não é logar tudo: é registrar contexto suficiente sem senhas, tokens ou dados sensíveis desnecessários."},{"type":"mechanics","title":"Como aplicar","items":["Inclua timestamp, nível e contexto útil.","Use request/correlation ID quando houver múltiplas camadas.","Monitore erros e latência do fluxo crítico.","Não registre segredos."]},{"type":"example","title":"Exemplo","body":"ERROR request_id=abc123 route=/api/pedidos status=500 code=DB_TIMEOUT duration_ms=2100"},{"type":"mistake","title":"Erro comum","body":"Logar payload completo de autenticação para ''facilitar debug'' e vazar credenciais."},{"type":"guided","question":"Qual dado ajuda a correlacionar a mesma operação entre serviços?","options":["Request/correlation ID.","Cor do terminal.","Número aleatório sem registro."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Usar logs, métricas, health checks e correlação de requisições para localizar falhas sem expor dados sensíveis.","Inclua timestamp, nível e contexto útil.","Use request/correlation ID quando houver múltiplas camadas.","Monitore erros e latência do fluxo crítico."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Observabilidade e diagnóstico de erros';
update nexora.lessons set objective='Definir problema, usuário, fluxo principal, arquitetura, escopo e critérios verificáveis do projeto final antes de construir.',estimated_minutes=60,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Sem escopo, o projeto final começa com uma lista de tecnologias e cresce sem saber qual problema resolve."},{"type":"concept","title":"Projeto final: planejamento e critérios de sucesso","body":"Projeto de portfólio começa pelo problema e pelo fluxo, não pela stack. Defina usuário, necessidade, dados, operações e critérios de sucesso. Depois escolha tecnologias que sustentam esse fluxo. O escopo deve caber no tempo disponível e produzir uma entrega demonstrável. Critérios objetivos ajudam a decidir o que entra e o que fica para depois."},{"type":"mechanics","title":"Como aplicar","items":["Defina problema e usuário.","Desenhe fluxo principal e dados.","Escolha stack pela necessidade.","Escreva critérios de aceite antes de implementar."]},{"type":"example","title":"Exemplo","body":"Problema: organizar atendimentos. Critério: usuário autenticado cria lead, move etapa, filtra pipeline e mantém dados após recarga; acesso de outro usuário é bloqueado."},{"type":"mistake","title":"Erro comum","body":"Definir sucesso como ''usar Java, Python, PHP e JavaScript no mesmo projeto''. Tecnologia não é objetivo do usuário."},{"type":"guided","question":"O que deve vir antes da escolha da stack?","options":["Problema, usuário e fluxo.","Quantidade de frameworks.","Nome do domínio."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Definir problema, usuário, fluxo principal, arquitetura, escopo e critérios verificáveis do projeto final antes de construir.","Defina problema e usuário.","Desenhe fluxo principal e dados.","Escolha stack pela necessidade."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Projeto final: planejamento e critérios de sucesso';
update nexora.lessons set objective='Entregar o projeto final funcional, testado, publicado e documentado com demonstração clara das decisões e limitações.',estimated_minutes=90,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O código está quase pronto, mas não há versão publicada, dados de demonstração ou roteiro para avaliar o projeto."},{"type":"concept","title":"Projeto final: construir, testar, publicar e apresentar","body":"A conclusão transforma implementação em produto avaliável. O projeto precisa de versão reproduzível, dados seguros de demonstração, testes do fluxo crítico, publicação, README e apresentação curta. Mostre problema, arquitetura, funcionalidades, como testar e o que ficou fora do escopo. Uma limitação conhecida documentada é melhor que uma promessa vaga."},{"type":"mechanics","title":"Como aplicar","items":["Congele escopo para concluir.","Faça QA e corrija defeitos críticos.","Publique e verifique build/health.","Prepare README e demonstração objetiva."]},{"type":"example","title":"Exemplo","body":"Entrega final: URL pública + repositório + README + conta/demo quando segura + checklist de testes + apresentação de 3–5 minutos do fluxo principal."},{"type":"mistake","title":"Erro comum","body":"Apresentar apenas slides enquanto o fluxo real não está publicado ou não pode ser reproduzido."},{"type":"guided","question":"Qual evidência final é mais forte?","options":["Produto funcionando, publicado e testável.","Lista de tecnologias.","Mockup sem fluxo."],"answer":0,"hint":"Escolha a opção que torna a integração verificável e segura.","feedback":"Correto. Essa decisão melhora contrato, operação e diagnóstico.","feedback_incorrect":"Revise o limite entre cliente, servidor e infraestrutura."},{"type":"recap","items":["Entregar o projeto final funcional, testado, publicado e documentado com demonstração clara das decisões e limitações.","Congele escopo para concluir.","Faça QA e corrija defeitos críticos.","Publique e verifique build/health."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=9) and title='Projeto final: construir, testar, publicar e apresentar';

